/// An assembled covariance (root.assemble_covariance), OWNED: copies
/// share it, the last copy releases it, and later assemblies are
/// independent. Entity arguments must come from the live model.
class Covariance {
public:
    Covariance() : c_(nullptr) {}
    explicit Covariance(ffi::Graph3Cov* c)
        : c_(c), guard_(c, ffi::graph3_cov_free) {}
    /// Error text of the last failed query on this assembly.
    const char* last_error() const { return ffi::graph3_cov_error(c_); }
    /// What the assembly decided -- the ordering it kept, what the
    /// candidates priced at, and how many symbolics it built.
    CovPlan plan() const {
        CovPlan p;
        ffi::graph3_cov_plan(c_, &p);
        return p;
    }
    /// Per-parameter standard deviations into out; returns the count
    /// or a negative code. Works on every CovMode incl. TriDiagonal.
    int32_t std_dev(const LmPoint3& e, double* out, uint32_t cap) {
        return ck_(ffi::graph3_lm_point3_std_dev(c_, e.raw(), out, cap));
    }
    /// Row-major dim x dim conditional covariance (all other
    /// parameters held fixed) into out; returns dim or a negative code.
    int32_t conditional(const LmPoint3& e, double* out, uint32_t cap) {
        return ck_(ffi::graph3_lm_point3_conditional_cov(c_, e.raw(), out, cap));
    }
    result<matrix3d, CovError> marginal(const LmPoint3& e) {
        double b[9];
        if (ck_(ffi::graph3_lm_point3_marginal_cov(c_, e.raw(), b, 9)) < 0) return fail<matrix3d>();
        return result<matrix3d, CovError>::ok(matrix3d::from_elements(
            b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7], b[8]));
    }
    /// Per-parameter standard deviations into out; returns the count
    /// or a negative code. Works on every CovMode incl. TriDiagonal.
    int32_t std_dev(const Pose3& e, double* out, uint32_t cap) {
        return ck_(ffi::graph3_pose3_std_dev(c_, e.raw(), out, cap));
    }
    /// Row-major dim x dim conditional covariance (all other
    /// parameters held fixed) into out; returns dim or a negative code.
    int32_t conditional(const Pose3& e, double* out, uint32_t cap) {
        return ck_(ffi::graph3_pose3_conditional_cov(c_, e.raw(), out, cap));
    }
    /// Row-major dim x dim into out; returns dim or a negative code.
    int32_t marginal(const Pose3& e, double* out, uint32_t cap) {
        return ck_(ffi::graph3_pose3_marginal_cov(c_, e.raw(), out, cap));
    }
    /// Row-major LmPoint3::param_count x LmPoint3::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const LmPoint3& a, const LmPoint3& b, double* out, uint32_t cap) {
        return ck_(ffi::graph3_lm_point3_lm_point3_cross_cov(c_, a.raw(), b.raw(), out, cap));
    }
    /// Row-major LmPoint3::param_count x Pose3::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const LmPoint3& a, const Pose3& b, double* out, uint32_t cap) {
        return ck_(ffi::graph3_lm_point3_pose3_cross_cov(c_, a.raw(), b.raw(), out, cap));
    }
    /// Row-major Pose3::param_count x LmPoint3::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const Pose3& a, const LmPoint3& b, double* out, uint32_t cap) {
        return ck_(ffi::graph3_pose3_lm_point3_cross_cov(c_, a.raw(), b.raw(), out, cap));
    }
    /// Row-major Pose3::param_count x Pose3::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const Pose3& a, const Pose3& b, double* out, uint32_t cap) {
        return ck_(ffi::graph3_pose3_pose3_cross_cov(c_, a.raw(), b.raw(), out, cap));
    }
private:
    /// A caught Rust panic (-2) throws; other codes pass through.
    int32_t ck_(int32_t n) const {
        if (n == -2) throw PanicError(ffi::graph3_cov_error(c_));
        return n;
    }
    template<class T> result<T, CovError> fail() {
        return result<T, CovError>::err({ffi::graph3_cov_error(c_)});
    }
    ffi::Graph3Cov* c_;
    std::shared_ptr<void> guard_;
};

/// `Graph3.poses`. Element pointers are STABLE across pushes (chunked storage).
class Graph3PosesVec {
public:
    explicit Graph3PosesVec(ffi::Graph3* h) : h_(h) {}
    uint32_t size() const { return ffi::graph3_poses_len(h_); }
    bool empty() const { return size() == 0; }
    void reserve(uint32_t additional) { ffi::graph3_poses_reserve(h_, additional); }
    /// Appends a default element and returns a wrapper for it.
    ///
    /// The wrapper holds a pointer INTO the collection, so it follows the
    /// std::vector rule: any later push may reallocate, and every wrapper
    /// taken before it -- including wrappers into collections nested inside
    /// these elements -- is then dangling. Either reserve() the count up
    /// front, or re-take the wrapper with operator[] after the growth.
    /// To hold on to an element across pushes, keep its Ref, not a wrapper.
    Pose3 push() { return Pose3(ffi::graph3_poses_push(h_)); }
    /// Wrapper for element `i`; see push() on how long it stays valid.
    Pose3 operator[](uint32_t i) { return Pose3(ffi::graph3_poses_at(h_, i)); }
    /// Front/back of a non-empty vec (empty = UB, like STL).
    Pose3 front() { return (*this)[0]; }
    Pose3 back() { return (*this)[size() - 1]; }
    /// Drops the last element; false when already empty.
    bool pop() { return ffi::graph3_poses_pop(h_); }
    void clear() { ffi::graph3_poses_clear(h_); }
    void truncate(uint32_t n) { ffi::graph3_poses_truncate(h_, n); }
    Pose3Ref ref_at(uint32_t i) const { return Pose3Ref{ffi::graph3_poses_ref_at(h_, i)}; }
    /// Ref of the first/last element; null when empty.
    Pose3Ref first_ref() const { return Pose3Ref{ffi::graph3_poses_first_ref(h_)}; }
    Pose3Ref last_ref() const { return Pose3Ref{ffi::graph3_poses_last_ref(h_)}; }
    Pose3 get(Pose3Ref r) { return Pose3(ffi::graph3_poses_get(h_, r.raw)); }
    /// True while r addresses a live element here.
    bool contains(Pose3Ref r) const { return ffi::graph3_poses_contains(h_, r.raw); }
    /// Like get, but empty for a stale or foreign ref.
    option<Pose3> try_get(Pose3Ref r) {
        ffi::Pose3* p = ffi::graph3_poses_try_get(h_, r.raw);
        return p ? option<Pose3>(Pose3(p)) : option<Pose3>();
    }
    /// Bidirectional iterator. Standard C++ contract: modifying the
    /// container while iterating is undefined behavior. Dereference
    /// yields a value wrapper (Pose3), like vector<bool> --
    /// reference is a value type.
    class iterator {
    public:
        using iterator_category = std::bidirectional_iterator_tag;
        using value_type = Pose3;
        using difference_type = std::ptrdiff_t;
        using reference = Pose3;
        struct arrow { Pose3 v; Pose3* operator->() { return &v; } };
        using pointer = arrow;

        iterator() : h_(nullptr), i_(0) {}
        iterator(ffi::Graph3* h, uint32_t i) : h_(h), i_(i) {}
        Pose3 operator*() const { return Pose3(ffi::graph3_poses_at(h_, i_)); }
        arrow operator->() const { return arrow{**this}; }
        iterator& operator++() { ++i_; return *this; }
        iterator& operator--() { --i_; return *this; }
        iterator operator++(int) { iterator t = *this; ++*this; return t; }
        iterator operator--(int) { iterator t = *this; --*this; return t; }
        bool operator==(const iterator& o) const { return i_ == o.i_; }
        bool operator!=(const iterator& o) const { return i_ != o.i_; }
    private:
        ffi::Graph3* h_;
        uint32_t i_;
    };
    iterator begin() { return iterator(h_, 0); }
    iterator end() { return iterator(h_, size()); }
    class reverse_iterator {
    public:
        using iterator_category = std::bidirectional_iterator_tag;
        using value_type = Pose3;
        using difference_type = std::ptrdiff_t;
        using reference = Pose3;
        using pointer = iterator::arrow;

        reverse_iterator() {}
        explicit reverse_iterator(iterator base) : base_(base) {}
        iterator base() const { return base_; }
        Pose3 operator*() const { iterator t = base_; --t; return *t; }
        pointer operator->() const { return pointer{**this}; }
        reverse_iterator& operator++() { --base_; return *this; }
        reverse_iterator& operator--() { ++base_; return *this; }
        reverse_iterator operator++(int) { reverse_iterator t = *this; ++*this; return t; }
        reverse_iterator operator--(int) { reverse_iterator t = *this; --*this; return t; }
        bool operator==(const reverse_iterator& o) const { return base_ == o.base_; }
        bool operator!=(const reverse_iterator& o) const { return base_ != o.base_; }
    private:
        iterator base_;
    };
    reverse_iterator rbegin() { return reverse_iterator(end()); }
    reverse_iterator rend() { return reverse_iterator(begin()); }
private:
    ffi::Graph3* h_;
};

